function rms(arr){ if(!arr||!arr.length) return 0; var s=0; for(var i=0;i<arr.length;i++) s+=arr[i]*arr[i]; return Math.sqrt(s/arr.length); }
function snrDb(signalPower, noisePower){ if(noisePower<=0) return Infinity; return 10*Math.log10(signalPower/noisePower); }
function addNoise(samples, snrDbTarget, rng){ rng=rng||Math.random; var srms=rms(samples);
  if(srms===0) return samples.slice();
  var targetNoiseRms = srms / Math.pow(10, snrDbTarget/20);
  var out=new Array(samples.length);
  for(var i=0;i<out.length;i++){ var g=(rng()*2-1 + (rng()*2-1))/Math.SQRT2; out[i]=samples[i]+targetNoiseRms*g; }
  return out;
}
function snrFromSamples(signal, noisy){ var N=signal.length; if(!N) return 0;
  var sp=0, np=0; for(var i=0;i<N;i++){ sp+=signal[i]*signal[i]; var d=noisy[i]-signal[i]; np+=d*d; } return snrDb(sp/N, np/N); }
